-- Generated by the CLI, ordered after IMP-02 because this repository contains
-- future-dated dependencies. No remote application is part of this phase.
alter table public.agent_outputs add column if not exists decision_context jsonb;
alter table public.agent_approvals add column if not exists decision_context jsonb;

create or replace function private.agent_output_source_hash(p_output jsonb, p_run_id uuid, p_organization_id uuid, p_store_id uuid, p_version_id uuid)
returns text language sql immutable security invoker set search_path = '' as $$
  select encode(sha256(convert_to(jsonb_build_object('run_id',p_run_id,'organization_id',p_organization_id,
    'store_id',p_store_id,'agent_version_id',p_version_id,
    'output',p_output - array['proposal_edits','proposal_decisions','decision_intent'])::text,'UTF8')),'hex');
$$;

create or replace function private.agent_output_actor_authorized(p_actor uuid, p_org uuid, p_store uuid, p_internal boolean)
returns boolean language sql stable security invoker set search_path = '' as $$
  select exists (
    select 1 from public.profiles p join public.organizations o on o.id=p_org
    where p.id=p_actor and p.is_active
      and o.status::text not in ('suspended','cancelled','pending_deletion')
      and (p_store is null or exists(select 1 from public.shopify_stores s where s.id=p_store and s.organization_id=p_org and s.is_active))
      and (not p_internal or p.is_platform_staff or private.is_consultant(p_actor))
      and (p.is_platform_staff
        or (private.is_consultant(p_actor) and exists(select 1 from public.consultant_assignments a
          where a.organization_id=p_org and a.consultant_user_id=p_actor and a.is_active))
        or exists(select 1 from public.organization_members m where m.organization_id=p_org and m.user_id=p_actor and m.is_active
          and (p.is_platform_staff or private.is_consultant(p_actor) or m.role::text in ('owner','manager'))
          and (coalesce(m.access_scope::text,'organization')='organization' or p_store=any(coalesce(m.store_ids,array[m.store_id])))))
  );
$$;

create or replace function public.claim_agent_output_decision_checked(
  p_output_id uuid, p_organization_id uuid, p_token uuid, p_decision text, p_edits jsonb, p_expected_output jsonb, p_actor uuid
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  v_output public.agent_outputs%rowtype;
  v_run public.agent_runs%rowtype;
  v_code text;
  v_hash text;
  v_context jsonb;
  v_edits jsonb;
begin
  if p_decision is null or p_decision not in ('approved','rejected') or p_token is null or p_actor is null
     or jsonb_typeof(p_edits) is distinct from 'array' or jsonb_typeof(p_expected_output) is distinct from 'object' then
    return jsonb_build_object('claimed',false,'reason','invalid_decision');
  end if;
  select * into v_output from public.agent_outputs where id=p_output_id and organization_id=p_organization_id for update;
  if not found or v_output.status <> 'pending_approval' then return jsonb_build_object('claimed',false,'reason','not_pending'); end if;
  select * into v_run from public.agent_runs where id=v_output.run_id and organization_id=p_organization_id;
  if not found then return jsonb_build_object('claimed',false,'reason','scope_mismatch'); end if;
  select d.code into v_code from public.agent_versions v join public.agent_definitions d on d.id=v.definition_id where v.id=v_run.agent_version_id;
  if v_code is null or not private.agent_output_actor_authorized(p_actor,p_organization_id,v_run.store_id,
      v_code='a08_gestor_conocimiento' or coalesce(v_run.objective,'') like '%[dashboard_scope=panel]%') then
    return jsonb_build_object('claimed',false,'reason','actor_not_authorized');
  end if;
  if p_decision='approved' and v_code='a08_gestor_conocimiento' then
    return jsonb_build_object('claimed',false,'reason','knowledge_audit_is_read_only');
  end if;
  if v_output.output is distinct from p_expected_output then return jsonb_build_object('claimed',false,'reason','source_changed'); end if;
  if exists(select 1 from public.agent_output_decision_claims where output_id=p_output_id and started_at>clock_timestamp()-interval '30 minutes') then
    return jsonb_build_object('claimed',false,'reason','decision_in_progress');
  end if;
  v_hash := private.agent_output_source_hash(v_output.output,v_run.id,p_organization_id,v_run.store_id,v_run.agent_version_id);
  v_context := v_output.decision_context;
  if v_context is null and nullif(v_output.output->>'decision_intent','') is not null then
    return jsonb_build_object('claimed',false,'reason','legacy_decision_requires_review');
  end if;
  if v_context is not null then
    if v_context->>'source_hash' is distinct from v_hash or v_context->>'decision' is distinct from p_decision
      or v_context->>'actor_id' is distinct from p_actor::text then
      return jsonb_build_object('claimed',false,'reason','decision_conflict');
    end if;
    v_edits := v_context->'edits';
    if p_edits <> '[]'::jsonb and p_edits is distinct from v_edits then
      return jsonb_build_object('claimed',false,'reason','decision_payload_changed');
    end if;
  else
    select coalesce(jsonb_agg(e order by (e->>'index')::integer),'[]'::jsonb) into v_edits from (
      select distinct on ((item->>'index')::integer) item e from
        jsonb_array_elements(coalesce(v_output.output->'proposal_edits','[]'::jsonb) || p_edits ||
          coalesce((select jsonb_agg(saved) from jsonb_array_elements(coalesce(v_output.output->'proposal_edits','[]'::jsonb)) saved where saved->>'skip'='true'),'[]'::jsonb)) with ordinality a(item,n)
        order by (item->>'index')::integer,n desc
    ) merged;
    v_context := jsonb_build_object('version','agent-decision-v1','source_hash',v_hash,'edits',v_edits,'actor_id',p_actor,
      'actor_side',case when exists(select 1 from public.profiles where id=p_actor and is_platform_staff) or private.is_consultant(p_actor) then 'consultant' else 'client' end,
      'decision',p_decision,'started_at',clock_timestamp(),'run_id',v_run.id,'organization_id',p_organization_id,
      'store_id',v_run.store_id,'agent_version_id',v_run.agent_version_id);
  end if;
  insert into public.agent_output_decision_claims(output_id,organization_id,token,decision,edits,started_at)
    values(p_output_id,p_organization_id,p_token,p_decision,v_edits,clock_timestamp())
    on conflict(output_id) do update set token=excluded.token,decision=excluded.decision,edits=excluded.edits,started_at=excluded.started_at;
  update public.agent_outputs set decision_context=v_context,
    output=output || jsonb_build_object('decision_intent',p_decision,'proposal_edits',v_edits),updated_at=clock_timestamp()
    where id=p_output_id returning * into v_output;
  return jsonb_build_object('claimed',true,'output',v_output.output,'run_id',v_output.run_id,'context',v_context);
end;
$$;

create or replace function public.validate_agent_output_decision_claim(p_output_id uuid, p_organization_id uuid, p_token uuid)
returns boolean language sql stable security invoker set search_path = '' as $$
  select exists(select 1 from public.agent_outputs o
    join public.agent_runs r on r.id=o.run_id and r.organization_id=o.organization_id
    join public.agent_versions v on v.id=r.agent_version_id join public.agent_definitions d on d.id=v.definition_id
    join public.agent_output_decision_claims c on c.output_id=o.id and c.organization_id=o.organization_id
    where o.id=p_output_id and o.organization_id=p_organization_id and o.status='pending_approval' and c.token=p_token
      and (c.decision<>'approved' or d.code<>'a08_gestor_conocimiento')
      and c.started_at>clock_timestamp()-interval '30 minutes'
      and o.decision_context->>'decision'=c.decision and o.decision_context->'edits'=c.edits
      and o.decision_context->>'source_hash'=private.agent_output_source_hash(o.output,r.id,o.organization_id,r.store_id,r.agent_version_id)
      and private.agent_output_actor_authorized((o.decision_context->>'actor_id')::uuid,o.organization_id,r.store_id,
        d.code='a08_gestor_conocimiento' or coalesce(r.objective,'') like '%[dashboard_scope=panel]%'));
$$;

create or replace function public.dismiss_agent_output_proposal(p_output_id uuid,p_organization_id uuid,p_index integer,p_actor uuid)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare v_output public.agent_outputs%rowtype; v_run public.agent_runs%rowtype; v_code text; v_edits jsonb; v_count integer; v_total integer;
begin
  select * into v_output from public.agent_outputs where id=p_output_id and organization_id=p_organization_id for update;
  if not found or v_output.status<>'pending_approval' then return jsonb_build_object('ok',false,'reason','not_pending'); end if;
  select * into v_run from public.agent_runs where id=v_output.run_id and organization_id=p_organization_id;
  select d.code into v_code from public.agent_versions v join public.agent_definitions d on d.id=v.definition_id where v.id=v_run.agent_version_id;
  if v_code is null or not private.agent_output_actor_authorized(p_actor,p_organization_id,v_run.store_id,
    v_code='a08_gestor_conocimiento' or coalesce(v_run.objective,'') like '%[dashboard_scope=panel]%') then
    return jsonb_build_object('ok',false,'reason','actor_not_authorized');
  end if;
  if v_output.decision_context is not null or nullif(v_output.output->>'decision_intent','') is not null
    or exists(select 1 from public.agent_output_decision_claims where output_id=p_output_id) then
    return jsonb_build_object('ok',false,'reason','decision_in_progress');
  end if;
  v_total := case when jsonb_typeof(v_output.output->'proposed_writes')='array' then jsonb_array_length(v_output.output->'proposed_writes') else 0 end;
  if p_index is null or p_index<0 or p_index>=v_total then return jsonb_build_object('ok',false,'reason','invalid_proposal_index'); end if;
  select coalesce(jsonb_agg(e),'[]'::jsonb) into v_edits from jsonb_array_elements(coalesce(v_output.output->'proposal_edits','[]'::jsonb)) e where (e->>'index')::integer<>p_index;
  v_edits := v_edits || jsonb_build_array(jsonb_build_object('index',p_index,'skip',true));
  select count(distinct (e->>'index')::integer) into v_count from jsonb_array_elements(v_edits) e
    where e->>'skip'='true' and (e->>'index')::integer>=0 and (e->>'index')::integer<v_total;
  update public.agent_outputs set output=output || jsonb_build_object('proposal_edits',v_edits),updated_at=clock_timestamp() where id=p_output_id;
  return jsonb_build_object('ok',true,'all_dismissed',v_count=v_total,'dismissed',v_count,'total',v_total);
end;
$$;

create or replace function public.finalize_agent_output_decision(
  p_output_id uuid,p_organization_id uuid,p_token uuid,p_actor uuid,p_decisions jsonb,p_reason text,p_reason_category text,p_tasks_created integer
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare v_output public.agent_outputs%rowtype; v_receipt uuid;
begin
  select * into v_output from public.agent_outputs where id=p_output_id and organization_id=p_organization_id for update;
  if not found or not public.validate_agent_output_decision_claim(p_output_id,p_organization_id,p_token)
    or v_output.decision_context->>'actor_id' is distinct from p_actor::text then
    return jsonb_build_object('ok',false,'reason','claim_expired_or_changed');
  end if;
  if jsonb_typeof(p_decisions) is distinct from 'array' or p_tasks_created is null or p_tasks_created<0 then
    return jsonb_build_object('ok',false,'reason','invalid_receipt');
  end if;
  insert into public.agent_approvals(output_id,organization_id,decision,decided_by,reason,reason_category,tasks_created,decision_context,decided_at)
    values(p_output_id,p_organization_id,v_output.decision_context->>'decision',p_actor,p_reason,p_reason_category,p_tasks_created,v_output.decision_context,clock_timestamp())
    on conflict(output_id) do update set decision=excluded.decision,decided_by=excluded.decided_by,reason=excluded.reason,
      reason_category=excluded.reason_category,tasks_created=excluded.tasks_created,decision_context=excluded.decision_context,decided_at=excluded.decided_at
    returning id into v_receipt;
  update public.agent_outputs set status=v_output.decision_context->>'decision',
    published_at=case when v_output.decision_context->>'decision'='approved' then clock_timestamp() else published_at end,
    output=output || jsonb_build_object('proposal_decisions',p_decisions),updated_at=clock_timestamp() where id=p_output_id;
  delete from public.agent_output_decision_claims where output_id=p_output_id and token=p_token;
  return jsonb_build_object('ok',true,'receipt_id',v_receipt,'source_hash',v_output.decision_context->>'source_hash');
end;
$$;

create or replace function public.record_agent_output_decision_progress(p_output_id uuid,p_organization_id uuid,p_token uuid,p_decisions jsonb)
returns boolean language plpgsql security invoker set search_path = '' as $$
begin
  perform 1 from public.agent_outputs where id=p_output_id and organization_id=p_organization_id for update;
  if not found or jsonb_typeof(p_decisions) is distinct from 'array'
    or not public.validate_agent_output_decision_claim(p_output_id,p_organization_id,p_token) then return false; end if;
  update public.agent_outputs set output=output || jsonb_build_object('proposal_decisions',p_decisions),updated_at=clock_timestamp() where id=p_output_id;
  return true;
end;
$$;

revoke all on function private.agent_output_source_hash(jsonb,uuid,uuid,uuid,uuid) from public,anon,authenticated;
revoke all on function private.agent_output_actor_authorized(uuid,uuid,uuid,boolean) from public,anon,authenticated;
revoke all on function public.claim_agent_output_decision_checked(uuid,uuid,uuid,text,jsonb,jsonb,uuid) from public,anon,authenticated;
revoke all on function public.validate_agent_output_decision_claim(uuid,uuid,uuid) from public,anon,authenticated;
revoke all on function public.dismiss_agent_output_proposal(uuid,uuid,integer,uuid) from public,anon,authenticated;
revoke all on function public.finalize_agent_output_decision(uuid,uuid,uuid,uuid,jsonb,text,text,integer) from public,anon,authenticated;
revoke all on function public.record_agent_output_decision_progress(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function private.is_consultant(uuid),private.agent_output_source_hash(jsonb,uuid,uuid,uuid,uuid),
  private.agent_output_actor_authorized(uuid,uuid,uuid,boolean),public.claim_agent_output_decision_checked(uuid,uuid,uuid,text,jsonb,jsonb,uuid),
  public.validate_agent_output_decision_claim(uuid,uuid,uuid),public.dismiss_agent_output_proposal(uuid,uuid,integer,uuid),
  public.finalize_agent_output_decision(uuid,uuid,uuid,uuid,jsonb,text,text,integer),
  public.record_agent_output_decision_progress(uuid,uuid,uuid,jsonb) to service_role;

-- A late worker cannot insert a task with a replaced/expired lease. The token
-- is consumed by the trigger and never stored in task metadata.
create or replace function private.check_agent_task_decision_claim()
returns trigger language plpgsql security invoker set search_path = '' as $$
declare v_output public.agent_outputs%rowtype; v_store uuid; v_token uuid;
begin
  if new.agent_output_id is null then return new; end if;
  select * into v_output from public.agent_outputs where id=new.agent_output_id for update;
  if v_output.decision_context is null then return new; end if;
  v_token := (new.metadata->>'ai_decision_token')::uuid;
  select store_id into v_store from public.agent_runs where id=v_output.run_id and organization_id=v_output.organization_id;
  if new.organization_id is distinct from v_output.organization_id
    or (new.store_id is not null and not exists(select 1 from public.shopify_stores where id=new.store_id and organization_id=new.organization_id and is_active))
    or (v_store is not null and new.store_id is distinct from v_store)
    or v_output.decision_context->>'decision' is distinct from 'approved'
    or new.agent_proposal_index is null or new.agent_proposal_index<0
    or v_output.output->'proposed_writes'->new.agent_proposal_index->>'kind' is distinct from 'task'
    or not public.validate_agent_output_decision_claim(v_output.id,v_output.organization_id,v_token) then
    raise exception 'agent_task_approval_invalid' using errcode='42501';
  end if;
  new.metadata := new.metadata - 'ai_decision_token';
  return new;
end;
$$;
drop trigger if exists tasks_check_agent_decision_claim on public.tasks;
create trigger tasks_check_agent_decision_claim before insert on public.tasks for each row execute function private.check_agent_task_decision_claim();
revoke all on function private.check_agent_task_decision_claim() from public,anon,authenticated;

create or replace function public.materialize_agent_output_note_checked(p_output_id uuid,p_organization_id uuid,p_token uuid,p_actor uuid,p_index integer,p_body text)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare v_output public.agent_outputs%rowtype; v_id uuid;
begin
  select * into v_output from public.agent_outputs where id=p_output_id and organization_id=p_organization_id for update;
  if not found or not public.validate_agent_output_decision_claim(p_output_id,p_organization_id,p_token)
    or v_output.decision_context->>'decision' is distinct from 'approved'
    or v_output.decision_context->>'actor_id' is distinct from p_actor::text
    or p_index is null or p_index<0 or v_output.output->'proposed_writes'->p_index->>'kind' is distinct from 'note'
    or nullif(btrim(p_body),'') is null then
    raise exception 'agent_note_approval_invalid' using errcode='42501';
  end if;
  insert into public.agent_output_notes(output_id,organization_id,author_user_id,author_kind,body,agent_proposal_index)
    values(p_output_id,p_organization_id,p_actor,'ai',left(p_body,4000),p_index)
    on conflict(output_id,agent_proposal_index) do nothing;
  select id into v_id from public.agent_output_notes where output_id=p_output_id and organization_id=p_organization_id and agent_proposal_index=p_index;
  return jsonb_build_object('id',v_id);
end;
$$;
revoke all on function public.materialize_agent_output_note_checked(uuid,uuid,uuid,uuid,integer,text) from public,anon,authenticated;
grant execute on function public.materialize_agent_output_note_checked(uuid,uuid,uuid,uuid,integer,text) to service_role;

-- Older API versions must not silently claim decisions without source binding.
revoke execute on function public.claim_agent_output_decision(uuid,uuid,uuid,text,jsonb) from public,anon,authenticated,service_role;

-- Once a human decision starts, a new source requires a new output. Progress
-- may change; the approved source, scope and edits may not.
create or replace function private.keep_agent_output_decision_source()
returns trigger language plpgsql security invoker set search_path = '' as $$
declare v_run public.agent_runs%rowtype;
begin
  if old.decision_context is null then return new; end if;
  select * into v_run from public.agent_runs where id=old.run_id and organization_id=old.organization_id;
  if new.run_id is distinct from old.run_id or new.organization_id is distinct from old.organization_id
    or new.decision_context is distinct from old.decision_context
    or new.output->'proposal_edits' is distinct from old.decision_context->'edits'
    or new.output->>'decision_intent' is distinct from old.decision_context->>'decision'
    or private.agent_output_source_hash(new.output,v_run.id,old.organization_id,v_run.store_id,v_run.agent_version_id)
      is distinct from old.decision_context->>'source_hash'
    or (old.status<>'pending_approval' and new.output->'proposal_decisions' is distinct from old.output->'proposal_decisions') then
    raise exception 'agent_output_decision_source_immutable' using errcode='42501';
  end if;
  return new;
end;
$$;
drop trigger if exists agent_outputs_keep_decision_source on public.agent_outputs;
create trigger agent_outputs_keep_decision_source before update on public.agent_outputs for each row execute function private.keep_agent_output_decision_source();
revoke all on function private.keep_agent_output_decision_source() from public,anon,authenticated;

create or replace function public.apply_a18_initiative_decision_checked(
  p_output_id uuid,p_organization_id uuid,p_token uuid,p_index integer,p_store_id uuid,p_previous_task_id uuid,
  p_action text,p_actor_user_id uuid,p_replacement jsonb
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare v_output public.agent_outputs%rowtype; v_source jsonb; v_previous public.tasks%rowtype; v_result jsonb;
begin
  select * into v_output from public.agent_outputs where id=p_output_id and organization_id=p_organization_id for update;
  if not found or not public.validate_agent_output_decision_claim(p_output_id,p_organization_id,p_token)
    or v_output.decision_context->>'decision' is distinct from 'approved'
    or v_output.decision_context->>'actor_id' is distinct from p_actor_user_id::text then
    raise exception 'a18_decision_claim_invalid' using errcode='42501';
  end if;
  v_source := v_output.output->'proposed_writes'->p_index->'initiative_change';
  if p_index is null or p_index<0 or not exists(select 1 from public.agent_runs r join public.agent_versions v on v.id=r.agent_version_id
      join public.agent_definitions d on d.id=v.definition_id where r.id=v_output.run_id and d.code='a18_plan_mensual')
    or v_source->>'action' is distinct from p_action or v_source->>'previous_task_id' is distinct from p_previous_task_id::text then
    raise exception 'a18_decision_source_mismatch' using errcode='42501';
  end if;
  select * into v_previous from public.tasks where id=p_previous_task_id and organization_id=p_organization_id for update;
  if not found or v_previous.store_id is distinct from p_store_id
    or (v_output.decision_context->>'store_id' is not null and v_output.decision_context->>'store_id' is distinct from p_store_id::text) then
    raise exception 'a18_decision_store_mismatch' using errcode='42501';
  end if;
  if v_previous.metadata->'ai_decision_receipt'->>'output_id'=p_output_id::text
    and v_previous.metadata->'ai_decision_receipt'->>'index'=p_index::text then
    return v_previous.metadata->'ai_decision_receipt'->'result';
  end if;
  v_result := public.approve_a18_monthly_initiative_change(p_organization_id,p_store_id,p_previous_task_id,p_action,p_actor_user_id,p_replacement);
  if v_result->>'new_task_id' is not null then
    update public.tasks set agent_output_id=p_output_id,agent_proposal_index=p_index where id=(v_result->>'new_task_id')::uuid and organization_id=p_organization_id;
  end if;
  update public.tasks set metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object('ai_decision_receipt',
    jsonb_build_object('output_id',p_output_id,'index',p_index,'result',v_result)) where id=p_previous_task_id and organization_id=p_organization_id;
  return v_result;
end;
$$;
revoke all on function public.apply_a18_initiative_decision_checked(uuid,uuid,uuid,integer,uuid,uuid,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.apply_a18_initiative_decision_checked(uuid,uuid,uuid,integer,uuid,uuid,text,uuid,jsonb) to service_role;
